"""A focused YAML reader for ordinary Taskfiles, implemented with the stdlib."""
import ast
import re


def _split(s, delimiter=','):
    out=[]; start=0; quote=None; depth=0; escaped=False
    for i,ch in enumerate(s):
        if escaped: escaped=False; continue
        if ch=='\\' and quote=='"': escaped=True; continue
        if quote:
            if ch==quote: quote=None
        elif ch in "'\"": quote=ch
        elif ch in '[{(': depth+=1
        elif ch in ']})': depth-=1
        elif ch==delimiter and depth==0:
            out.append(s[start:i].strip()); start=i+1
    out.append(s[start:].strip())
    return out


def _colon(s):
    parts=_split(s,':')
    return len(parts)>1


def _keyval(s):
    # Locate the first colon outside quotes/collections (mapping keys cannot be collections here).
    quote=None; escaped=False
    for i,ch in enumerate(s):
        if escaped: escaped=False; continue
        if ch=='\\' and quote=='"': escaped=True; continue
        if quote:
            if ch==quote: quote=None
        elif ch in "'\"": quote=ch
        elif ch==':': return s[:i].strip(),s[i+1:].strip()
    return None,None


def _scalar(src):
    s=src.strip()
    if not s:return ''
    if s[0] in "'\"" and s[-1:]==s[0]:
        if s[0]=='"':
            try:return ast.literal_eval(s)
            except Exception:return s[1:-1]
        return s[1:-1].replace("''", "'")
    if s[0]=='[' and s[-1:]==']':
        inner=s[1:-1].strip()
        return [] if not inner else [_scalar(x) for x in _split(inner)]
    if s[0]=='{' and s[-1:]=='}':
        inner=s[1:-1].strip(); out={}
        if inner:
            for part in _split(inner):
                k,v=_keyval(part)
                if k is not None:out[str(_scalar(k))]=_scalar(v)
        return out
    low=s.lower()
    if low=='true':return True
    if low=='false':return False
    if low in ('null','~'):return None
    if re.fullmatch(r'[+-]?0[0-7]+', s):
        try:return int(s,8)
        except ValueError:pass
    if re.fullmatch(r'[-+]?(?:0|[1-9][0-9]*)',s):
