"""Task execution helpers."""
import os, subprocess, sys, shlex, glob, hashlib, json, concurrent.futures
from templating import render, resolve_vars


def _subst(s, values):
    return render(s, values) if isinstance(s, str) else s


def _patterns(value):
    result=[]
    for item in value or []:
        if isinstance(item,str): result.append(item)
        elif isinstance(item,dict) and item.get('exclude') is None:
            result.extend(map(str,item.keys()))
    return result


def _file_signature(task, task_dir, root, name):
    sources=_patterns(task.get('sources'))
    if not sources:return None
    # Task uses a deterministic checksum over the task definition and source files.
    records=[]
    for pattern in sources:
        paths=glob.glob(os.path.join(task_dir,pattern),recursive=True)
        if not paths: records.append(pattern); continue
        for path in sorted(paths):
            try:
                if os.path.isdir(path):
                    for child in sorted(glob.glob(os.path.join(path,'**','*'),recursive=True)):
                        if not os.path.isfile(child): continue
                        with open(child,'rb') as f: digest=hashlib.md5(f.read()).hexdigest()
                        records.extend((os.path.relpath(child,root),digest))
                else:
                    with open(path,'rb') as f: digest=hashlib.md5(f.read()).hexdigest()
                    records.extend((os.path.relpath(path,root),digest))
            except OSError: records.append(path)
    payload=json.dumps([task,records],sort_keys=True,default=str,separators=(',',':'))
    return hashlib.md5(payload.encode()).hexdigest()


def run_tasks(config, names, *, cwd=None, dry=False, silent=False, verbose=False, force=False, cli_args='', cli_args_list=None, cli_vars=None, context_vars=None, exit_code=False, output=None, group_begin='', group_end='', group_error_only=False, parallel=False, concurrency=None):
    """Run task definitions from normalized Taskfile dictionary. Return exit status."""
    tasks=config.get('tasks') or {}
    cwd=cwd or os.getcwd()
    output = output or config.get('output') or 'interleaved'
    if isinstance(output, dict):
        output = 'group' if 'group' in output else 'interleaved'
    values=resolve_vars(config.get('vars') or {}, env=os.environ, cwd=cwd)
    values.update(cli_vars or {})
    values.update(context_vars or {})
    values['CLI_ARGS']=cli_args
    try: values['CLI_ARGS_LIST']=list(cli_args_list) if cli_args_list is not None else shlex.split(cli_args)
    except ValueError: values['CLI_ARGS_LIST']=cli_args.split()
    active=set(); done=set()
    if not names: names=['default']
    def run(name, overrides=None):
        called_as=name
        if name not in tasks:
            for task_name, definition in tasks.items():
                aliases=definition.get('aliases',[]) if isinstance(definition,dict) else []
                if isinstance(aliases,str): aliases=[aliases]
                if name in aliases:
                    name=task_name
                    break
        if name in done: return 0
        if name in active:
            print('task: Task called too many times (recursion limit)',file=sys.stderr); return 204
        task=tasks.get(name)
        if task is None:
            print(f'task: Task "{name}" does not exist',file=sys.stderr); return 200
        if isinstance(task,str): task={'cmds':[task]}
        elif isinstance(task,list): task={'cmds':task}
        task=task or {}; active.add(name)
        if verbose: print(f'task: "{name}" started',file=sys.stderr,flush=True)
        local_values=dict(values)
        local_values.update(overrides or {})
        local_values['TASK']=name
        local_values['ALIAS']=called_as
        if task.get('_TASKFILE'):
            local_values['TASKFILE']=task['_TASKFILE']
        if task.get('_TASKFILE_DIR'):
            local_values['TASKFILE_DIR']=task['_TASKFILE_DIR']
        task_env=dict(config.get('env') or {})
        task_env.update(task.get('env') or {})
        child_env=os.environ.copy()
        dotenv_files=[]
        for collection in (task.get('dotenv') or [], config.get('dotenv') or []):
            if isinstance(collection,str): collection=[collection]
            dotenv_files.extend(collection)
        for filename in dotenv_files:
            filename=_subst(filename,local_values)
            dotenv_path=filename if os.path.isabs(filename) else os.path.join(cwd,filename)
            try:
                for line in open(dotenv_path,encoding='utf-8-sig'):
                    line=line.strip()
                    if not line or line.startswith('#'): continue
                    if line.startswith('export '): line=line[7:].lstrip()
